{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    if goal > max(bucket_one, bucket_two):
        raise ValueError("goal is larger than both buckets")

    sizes = (bucket_one, bucket_two)
    start = (bucket_one, 0) if start_bucket == "one" else (0, bucket_two)

    def forbidden(state):
        if start_bucket == "one":
            return state[0] == 0 and state[1] == bucket_two
        return state[1] == 0 and state[0] == bucket_one

    def next_states(state):
        a, b = state
        pour_ab = min(a, sizes[1] - b)
        pour_ba = min(b, sizes[0] - a)
        return (
            (sizes[0], b), (a, sizes[1]),  # fill
            (0, b), (a, 0),  # empty
            (a - pour_ab, b + pour_ab),  # pour one -> two
            (a + pour_ba, b - pour_ba),  # pour two -> one
        )

    queue = deque([(start, 1)])
    seen = {start}
    while queue:
        (a, b), moves = queue.popleft()
        if a == goal:
            return moves, "one", b
        if b == goal:
            return moves, "two", a
        for state in next_states((a, b)):
            if state not in seen and not forbidden(state):
                seen.add(state)
                queue.append((state, moves + 1))

    raise ValueError("goal cannot be reached with these buckets")
"}

